/**
 * The compatibility corpus (core protection, plan item 4): share links, `last.json` sessions,
 * saved-viewpoint lists and `.schedule.json` files **as past builds wrote them**, each decoded
 * and restored by today's code to the state the recorded decisions say it must reach.
 *
 * The files are in `tests/fixtures/compat/<version>/`, made by that build's own encoders
 * (`tests/fixtures/compat/make-corpus.cjs`; the folder's README says which commit made each).
 * They are never regenerated by today's encoder: a change that cannot read them any more is a
 * change that breaks links and saved work people already have.
 *
 * Each expectation is derived from a decision, not from what the code happens to do today:
 *
 * - 2026-10-01 — a payload or viewpoint with only the single `section` restores it onto the
 *   plane of its `kind`, the other plane cleared (`sectionsOf`); one with `sections` takes both.
 * - 2026-10-09 — `idStride` absent means the design's 1 000 000, read against the elements that
 *   are really there (`liveHidden`); ids move from each file's saved slot to its live one.
 * - 2026-10-09 — `units` absent leaves the boot model's unit; present, it is restored.
 * - 2026-11-07 — a camera is restored only under the `identity` frame key; an old P key restores
 *   everything else and frames the extents instead.
 * - 2026-10-08 — the base point (`coords`) is still written and is never restored.
 * - 2026-09-25 — a schedule file is read by ifcTable's strict `parseScheduleDef`.
 */
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { federate, type Federation } from '../../src/shared/federate'
import { SessionEnvelope } from '../../src/shared/ipc-contract'
import {
  payloadFromLink,
  restorableIds,
  type SessionFile,
  type SessionPayload
} from '../../src/shared/session-codec'
import { NO_PLANE, type Sections } from '../../src/shared/sections'
import type { SessionCoords } from '../../src/shared/session-codec'
import { parseScheduleDef } from '../../src/schedule/schedule/def'
import { mockModelIndex } from '../../src/renderer/dev/mock-adapter'
import { setViewer, useShell, type ShellState } from '../../src/renderer/state/shell'
import { memoryStorage, resetShell, stubViewer } from './stub-viewer'

const DIR = join(__dirname, '..', 'fixtures', 'compat')
const read = (version: string, file: string): string => readFileSync(join(DIR, version, file), 'utf8')
const st = (): ShellState => useShell.getState()

/** The scenario every build was fed (`make-corpus.cjs`), as each must come back. */
const CAM = { theta: 0.8, phi: 1.1, dist: 42.5, half: 18.25, target: [3.5, 7.25, 4], proj: 'ortho' }
const LEVEL_L2 = { name: 'L2', offset: 1200, flip: false, cut: true }
const GRID_C_PREVIEW = { name: 'C', offset: 500, flip: true, cut: false }
const STACK = [
  {
    id: 's1',
    on: true,
    action: 'isolate',
    color: '#35C4B6',
    rules: [{ prop: 'IfcEntity', op: '=', val: 'IfcWall', join: 'and' }]
  }
]
const PATHS = { ARC: '/Users/me/models/Tower A ARC.ifc', STR: '/Users/me/models/Tower A STR.ifc' }

interface Expected {
  /** What `sections` must be after the restore. */
  sections: Sections
  /** The display unit after the restore, the live boot unit being `mm`. */
  units: 'mm' | 'm' | 'ft'
  /** Whether the camera is pointed (`setCamera`) or the extents framed instead. */
  camera: 'restored' | 'framed'
}

/** One build each. A payload's own keys say why. */
const SESSIONS: Record<string, Expected> = {
  // Single `section` (level L2), no `idStride`, no `units`, frame key P from the site placement.
  'v1.0.0': { sections: { grid: NO_PLANE, level: LEVEL_L2 }, units: 'mm', camera: 'framed' },
  // Both planes, no `idStride`, no `units`; the boot model had no site placement: `identity`.
  'v1.2.0': { sections: { grid: GRID_C_PREVIEW, level: LEVEL_L2 }, units: 'mm', camera: 'restored' },
  // `idStride` and `units: ft`; frame key P from an `IfcMapConversion`.
  'v1.3.0': { sections: { grid: GRID_C_PREVIEW, level: LEVEL_L2 }, units: 'ft', camera: 'framed' },
  // Today's own: `identity`, `units: m`.
  current: { sections: { grid: GRID_C_PREVIEW, level: LEVEL_L2 }, units: 'm', camera: 'restored' }
}

interface Hid {
  model: string
  guid: string
  savedId: number
}

/** Every viewer call the store made, by name. */
let calls: { name: string; args: unknown[] }[] = []
const called = (name: string): unknown[][] => calls.filter((c) => c.name === name).map((c) => c.args)

function recordingViewer(): void {
  const rec =
    (name: string) =>
    (...args: unknown[]) =>
      void calls.push({ name, args })
  setViewer(
    stubViewer(
      Object.fromEntries(
        [
          'setCamera',
          'frameExtents',
          'setSections',
          'setShadows',
          'setTheme',
          'setUnits',
          'setGrids',
          'setLevels',
          'setSnap',
          'setPickable',
          'setModelColors'
        ].map((n) => [n, rec(n)])
      )
    )
  )
}

/** The live ids of the elements a build hid, found by model and GlobalId. */
function liveIds(fed: Federation, hid: readonly Hid[]): number[] {
  return hid
    .map((h) => {
      const el = fed.elements.find((e) => e.model === h.model && e.guid === h.guid)
      if (!el) throw new Error(`the mock no longer has ${h.model} ${h.guid}`)
      return el.id
    })
    .sort((a, b) => a - b)
}

/**
 * Open a federation, after an empty one: `commitModels` re-reads the viewpoint list only when
 * the building's key changes, and that key is module state that outlives `resetShell`.
 */
function open(fed: Federation): void {
  st().commitModels(federate([]))
  st().commitModels(fed)
}

beforeEach(() => {
  resetShell()
  setViewer(null)
  calls = []
  vi.stubGlobal('localStorage', memoryStorage())
})
afterEach(() => {
  setViewer(null)
  vi.unstubAllGlobals()
})

describe.each(Object.entries(SESSIONS))('a session written by %s', (version, want) => {
  const linkText = read(version, 'link.txt').trim()
  const last = JSON.parse(read(version, 'last.json')) as unknown
  const hid = JSON.parse(read(version, 'hidden.json')) as Hid[]

  it('decodes: the link and last.json carry the same payload, and last.json is a valid envelope', () => {
    const fromLink = payloadFromLink(linkText)
    const envelope = SessionEnvelope.safeParse(last)
    expect(envelope.success).toBe(true)
    expect(fromLink).not.toBeNull()
    expect(fromLink).toEqual(envelope.data?.payload)
  })

  it('restores the recorded state through the link, its files open on other slots', () => {
    const p = payloadFromLink(linkText) as SessionPayload
    // Opened in the other order: STR on slot 0, ARC on slot 1. Every id must move with its file.
    const fed = federate([mockModelIndex('STR'), mockModelIndex('ARC')])
    open(fed)
    recordingViewer()
    const coordsBefore: SessionCoords = st().coords
    expect(st().units).toBe('mm')
    expect(st().theme).toBe('dark')

    const live: SessionFile[] = fed.models.map((m) => ({
      key: m.meta.modelKey,
      path: PATHS[m.meta.modelKey as 'ARC' | 'STR'],
      name: '',
      sha256: '',
      slot: m.slot
    }))
    // The open path's own composition (`upload-pipeline.ts`): ids first, then the restore.
    st().applySession({ ...p, ...restorableIds(p, live, (id) => fed.byId.has(id)) })

    const s = st()
    expect(Object.keys(s.hidden).map(Number).sort((a, b) => a - b), 'hidden ids').toEqual(liveIds(fed, hid))
    expect(s.active).toBe('STR')
    expect(s.sections, 'section planes').toEqual(want.sections)
    expect(s.units).toBe(want.units)
    expect(s.coords, 'the base point is never restored').toEqual(coordsBefore)
    expect(s.coords).not.toEqual(p.coords)
    expect(s).toMatchObject({
      theme: 'light',
      treeMode: 'type',
      grids: true,
      levels: false,
      snap: false,
      dims: true,
      nativeMats: false,
      modelColors: { ARC: '#D8D2C6' },
      storeyVis: { Roof: false },
      modelVis: {},
      stack: STACK,
      hlColor: '#E8A33D',
      view: null
    })
    // The viewer is told what the state now says.
    expect(called('setShadows')).toEqual([[false]])
    expect(called('setTheme')).toEqual([['light']])
    expect(called('setSections').at(-1)).toEqual([
      {
        grid: want.sections.grid.name
          ? { kind: 'grid', name: 'C', offset: 0.5, flip: true, cut: false }
          : null,
        level: { kind: 'storey', name: 'L2', offset: 1.2, flip: false, cut: true }
      }
    ])
    if (want.camera === 'restored') {
      expect(called('setCamera')).toEqual([[CAM]])
      expect(called('frameExtents')).toEqual([])
    } else {
      expect(called('setCamera')).toEqual([])
      expect(called('frameExtents')).toEqual([[]])
    }
  })

  it('restores no element id when one of its files is not open', () => {
    const p = payloadFromLink(linkText) as SessionPayload
    const fed = federate([mockModelIndex('ARC')])
    const live: SessionFile[] = [{ key: 'ARC', path: PATHS.ARC, name: '', sha256: '', slot: 0 }]
    expect(restorableIds(p, live, (id) => fed.byId.has(id))).toEqual({ hidden: {}, active: null })
  })
})

describe.each(Object.entries(SESSIONS))('saved viewpoints written by %s', (version, want) => {
  const stored = JSON.parse(read(version, 'viewpoints.json')) as { key: string; value: string }
  const hid = JSON.parse(read(version, 'hidden.json')) as Hid[]

  it('are read from their storage key and restore the recorded state', () => {
    localStorage.setItem(stored.key, stored.value)
    // A viewpoint records no files: it is restored onto the slots the models have now, which
    // here are the slots it was saved on.
    const fed = federate([mockModelIndex('ARC'), mockModelIndex('STR')])
    open(fed)
    recordingViewer()
    const [first, second] = st().views
    expect(st().views.map((v) => v.name)).toEqual(['Viewpoint 1', 'Viewpoint 2'])

    st().restoreView(first)
    const s = st()
    expect(Object.keys(s.hidden).map(Number).sort((a, b) => a - b), 'hidden ids').toEqual(liveIds(fed, hid))
    expect(s.sections, 'section planes').toEqual(want.sections)
    expect(s).toMatchObject({
      active: 'STR',
      storeyVis: { Roof: false },
      stack: STACK,
      grids: true,
      levels: false,
      activeView: first.id
    })
    if (want.camera === 'restored') {
      expect(called('setCamera')).toEqual([[CAM]])
      expect(called('frameExtents')).toEqual([])
    } else {
      expect(called('setCamera')).toEqual([])
      expect(called('frameExtents')).toEqual([[]])
    }

    calls = []
    st().restoreView(second)
    expect(st()).toMatchObject({ hidden: {}, stack: [], active: null, sections: { grid: NO_PLANE, level: NO_PLANE } })
    // Saved with no camera: neither pointed nor framed.
    expect(called('setCamera')).toEqual([])
    expect(called('frameExtents')).toEqual([])
  })
})

describe.each(['v1.1.0-beta.1', 'v1.2.0', 'current'])('schedule files written by %s', (version) => {
  it.each(['doors.schedule.json', 'walls.schedule.json'])('%s opens with everything it was written with', (file) => {
    const written = JSON.parse(read(version, file)) as Record<string, unknown>
    const def = parseScheduleDef(written)
    // Every key the file holds comes back as written; the parser may only add its own defaults
    // (an appearance key the file left out), never drop or change one.
    expect(def).toMatchObject(written)
    // And what it opens as is a fixed point: saved again and reopened, nothing moves.
    expect(parseScheduleDef(JSON.parse(JSON.stringify(def)))).toEqual(def)
  })
})
